       @Override
       public Collection<String> getApplicableElements() {
           return Collections.singletonList("item");
       }

       @Override
       public void visitElement(XmlContext context, Element element) {
           String typeAttr = element.getAttribute("type");
           if (typeAttr == null || typeAttr.isEmpty()) {
               return;
           }

           NodeList children = element.getChildNodes();
           String text = null;
           Node textNode = null;
           for (int i = 0; i < children.getLength(); i++) {
               Node child = children.item(i);
               if (child.getNodeType() == Node.TEXT_NODE) {
                   text = child.getNodeValue().trim();
                   textNode = child;
                   break;
               }
           }

           if (text == null || !text.startsWith("@")) {
               return;
           }

           // Skip @+id/ or ?attr/ etc.
           if (text.startsWith("@+")) {
               return;
           }

           String ref = text.substring(1); // remove @
           int colon = ref.indexOf(':');
           if (colon != -1) {
               ref = ref.substring(colon + 1);
           }
           int slash = ref.indexOf('/');
           if (slash == -1) {
               return; // not a valid resource reference format
           }

           String refType = ref.substring(0, slash);
           if (!typeAttr.equals(refType)) {
               Location location = textNode != null ? context.getLocation(textNode) : context.getLocation(element);
               String message = String.format(
                   "Resource alias type mismatch: expected `%1$s` but referenced `%2$s`",
                   typeAttr, refType);
               context.report(ISSUE, location, message);
           }
       }
   }
   ```

